FILE: app/src/release.ts
```ts
import { getAnimationGroups, stopAnimation } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

export function releaseProperty(manager: AnimationManager, target: object, path: string): void {
    const segments = path.split(".");
    const lastSegment = segments[segments.length - 1];

    // Resolve the object that owns the last path segment.
    // Per the notes, targetedAnimations entries store { target: owner-of-last-segment, path: last-segment }.
    let owner: unknown = target;
    for (let i = 0; i < segments.length - 1; i++) {
        owner = (owner as Record<string, unknown>)[segments[i]];
    }

    if (owner == null) return;

    const groups = getAnimationGroups(manager);
    for (const group of groups) {
        const targeted = group.targetedAnimations;
        for (const ta of targeted) {
            if (ta.target === owner && ta.path === lastSegment) {
                stopAnimation(group);
                break;
            }
        }
    }
}
```

I wrote `src/release.ts` which resolves the dotted path to find the owner object and last segment, then iterates every group on the manager via `getAnimationGroups` and calls `stopAnimation` on any group whose `targetedAnimations` contain a matching `{ target, path }` pair (per note 47, the entry stores the object owning the last path part and that part itself). I'm not sure whether `stopAnimation` is the ideal choice versus simply setting `isPlaying = false` if you ever want the group to be replayable later without a full reset of `currentTime`—but `stopAnimation` is the cleanest "nothing writes to that property anymore" guarantee the API offers.
